UPDATE batch.config_approval
   SET approval_status = #{param.targetStatus},
       reviewed_by = #{param.reviewedBy},
       reviewed_at = CURRENT_TIMESTAMP,
       review_comment = #{param.reviewComment},
       updated_at = CURRENT_TIMESTAMP
 WHERE tenant_id = #{param.tenantId}
   AND id = #{param.id}
   AND approval_status = #{param.expectedStatus}
